example.code:
var resultado = await client.ValidateAsync(new LicenseValidationRequest
{
    IdLicenca = 12345,
    Cnpj = "00073196000144",
    Chave = "MAQUINA-01"
});

if (resultado.IsActive)
    Console.WriteLine("Licença válida!");
else
    Console.WriteLine($"Bloqueada: {resultado.Licenca?.Mensagem}");

var clientes = cnpjs.Select(c => new BatchValidationItem { Cnpj = c, DataUltimoAcesso = DateTime.UtcNow });
var resultados = await client.ValidateBatchAsync(clientes);

var naoAutorizados = resultados.Where(r => r.Licenca?.Status == LicenseKeyStatus.NotAuthorized).ToList();

var info = await client.RevokeAsync(new LicenseRevocationRequest
{
    IdLicenca = 12345,
    Cnpj = "00073196000144",
    Chave = "MAQUINA-01"
});

if (info.Status == LicenseKeyStatus.Revoked)
    Console.WriteLine("Revogada com sucesso.");
